import { v2 as cloudinary } from 'cloudinary';

cloudinary.config({
  cloud_name: process.env.CLOUDINARY_CLOUD_NAME,
  api_key: process.env.CLOUDINARY_API_KEY,
  api_secret: process.env.CLOUDINARY_API_SECRET,
});

// Upload from file path
const result = await cloudinary.uploader.upload('./profile.jpg', {
  public_id: 'users/user_123/profile',
  folder: 'users',
  overwrite: true,
  resource_type: 'image',
});

console.log('Uploaded URL:', result.secure_url);
console.log('Public ID:', result.public_id);

import { v2 as cloudinary } from 'cloudinary';

cloudinary.config({ /* ... */ });

// Generate a URL with transformations — no API call needed!
const url = cloudinary.url('users/user_123/profile', {
  width: 200,
  height: 200,
  crop: 'fill',
  gravity: 'face', // Auto-detect and center on face
  quality: 'auto',
  fetch_format: 'auto', // Serve WebP to browsers that support it
});

console.log('Transformed URL:', url);
// Outputs: https://res.cloudinary.com/your-cloud/image/upload/w_200,h_200,c_fill,g_face,q_auto,f_auto/users/user_123/profile
